// Modal container chỉ quan tâm đến logic mở/đóng và khung giao diện:
interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  children: React.ReactNode;
}

export function Modal({ isOpen, onClose, children }: ModalProps) {
