// Ví dụ thực tế: Dừng/chạy Stopwatch
function Stopwatch() {
  const [seconds, setSeconds] = useState(0); // Cần render UI -> dùng useState
  const timerRef = useRef<NodeJS.Timeout | null>(null); // Không render UI -> useRef

  const start = () => {
    if (timerRef.current !== null) return;
    timerRef.current = setInterval(() => setSeconds(s => s + 1), 1000);
  };

  const stop = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  return <div>{seconds}s <button onClick={start}>Start</button><button onClick={stop}>Stop</button></div>;
}

