import { useState, useTransition } from 'react';

function SearchApp() {
  const [text, setText] = useState('');
  const [query, setQuery] = useState('');
  const [isPending, startTransition] = useTransition();

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    // 1. Cập nhật khẩn cấp (Urgent): Ô input nhảy chữ ngay lập tức
    setText(e.target.value);

    // 2. Cập nhật chuyển tiếp (Transition): Tác vụ lọc nặng có thể bị ngắt
    startTransition(() => {
      setQuery(e.target.value);
    });
  };

  return (
    <div>
      <input value={text} onChange={handleChange} />
      {isPending && <p>Đang lọc kết quả...</p>}
      <HeavyList query={query} />
    </div>
  );
}

import { useState, useTransition, Suspense, lazy } from 'react';

const AnalyticsTab = lazy(() => import('./AnalyticsTab'));
const SettingsTab = lazy(() => import('./SettingsTab'));

function TabContainer() {
  const [tab, setTab] = useState<'analytics' | 'settings'>('analytics');
  const [isPending, startTransition] = useTransition();

  const selectTab = (nextTab: 'analytics' | 'settings') => {
    // Bọc trong startTransition để tránh fallback nhấp nháy
    startTransition(() => {
      setTab(nextTab);
    });
  };

  return (
    <div>
      <button onClick={() => selectTab('analytics')}>Analytics</button>
      <button onClick={() => selectTab('settings')}>Settings</button>
      {isPending && <span className="spinner-sm">Loading next tab...</span>}

      <Suspense fallback={<MainSkeleton />}>
        <div style={{ opacity: isPending ? 0.7 : 1 }}>
          {tab === 'analytics' ? <AnalyticsTab /> : <SettingsTab />}
        </div>
      </Suspense>
    </div>
  );
}

