// 1. React Server Component (Chạy trên server, code gọn gàng, an toàn):
// app/products/[id]/page.tsx
export default async function ProductPage({ params }: { params: { id: string } }) {
  // Gọi DB trực tiếp hoặc fetch nội bộ, không lộ secret key
  const product = await db.product.findUnique({ where: { id: params.id } });
  return <div><h1>{product.title}</h1><p>${product.price}</p></div>;
