// 2. Client-side fetching cũ (Boilerplate nhiều, trễ 1 nhịp network):
function ProductClient({ id }: { id: string }) {
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    fetch(`/api/products/${id}`).then(r => r.json()).then(d => { setProduct(d); setLoading(false); });
  }, [id]);
  if (loading) return <Spinner />;
  return <div>...</div>;
}

interface AsyncStateViewProps<T> {
  isLoading: boolean;
  error: Error | null;
  data: T[] | null;
  onRetry: () => void;
  renderItem: (items: T[]) => React.ReactNode;
}

export function ListView<T>({ isLoading, error, data, onRetry, renderItem }: AsyncStateViewProps<T>) {
  if (isLoading) return <ListSkeleton count={5} />;
  if (error) return <ErrorAlert message={error.message} onRetry={onRetry} />;
  if (!data || data.length === 0) return <EmptyState title="Không có dữ liệu" actionText="Tạo mới" />;
  return <>{renderItem(data)}</>;
}

