import React, { createContext, useContext, useState } from 'react';

// 1. Khởi tạo Context ngầm
const TabsContext = createContext<{ active: string; setActive: (id: string) => void } | null>(null);

// 2. Component cha nắm state
export function Tabs({ defaultTab, children }: { defaultTab: string; children: React.ReactNode }) {
  const [active, setActive] = useState(defaultTab);
  return <TabsContext.Provider value={{ active, setActive }}>{children}</TabsContext.Provider>;
}

// 3. Các component con
Tabs.Trigger = function TabTrigger({ id, children }: { id: string; children: React.ReactNode }) {
  const ctx = useContext(TabsContext);
  if (!ctx) throw new Error('TabTrigger must be used within <Tabs>');
  return <button className={ctx.active === id ? 'active' : ''} onClick={() => ctx.setActive(id)}>{children}</button>;
};

Tabs.Panel = function TabPanel({ id, children }: { id: string; children: React.ReactNode }) {
  const ctx = useContext(TabsContext);
  if (!ctx) throw new Error('TabPanel must be used within <Tabs>');
  return ctx.active === id ? <div>{children}</div> : null;
};

// 4. Sử dụng cực kỳ thanh lịch và linh hoạt:
// <Tabs defaultTab="home"><Tabs.Trigger id="home">Home</Tabs.Trigger><Tabs.Panel id="home">Nội dung</Tabs.Panel></Tabs>

function LifecycleDemo() {
  useEffect(() => {
    // 1. MOUNT: Chạy 1 lần khi component sinh ra và gắn vào DOM
    console.log('Component mounted');

    // 3. UNMOUNT: Hàm return chạy khi component bị gỡ khỏi DOM
    return () => {
      console.log('Component unmounted');
    };
  }, []);

  useEffect(() => {
    // 2. UPDATE: Chạy mỗi khi count thay đổi
    console.log('Component updated count:', count);
  }, [count]);

  return <div>Lifecycle</div>;
}

