// 2. CUSTOM HOOK (Có dùng hook React, gắn với lifecycle):
export function useWindowWidth(): number {
  const [width, setWidth] = useState(() => window.innerWidth);
  useEffect(() => {
    const onResize = () => setWidth(window.innerWidth);
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);
  return width;
}

import { useState, useEffect } from 'react';

export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    // Thiết lập timer cập nhật sau khoảng thời gian delay
    const timer = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    // Cleanup: Hủy timer nếu value thay đổi trước khi hết thời gian delay
    return () => {
      clearTimeout(timer);
    };
  }, [value, delay]);

  return debouncedValue;
}

// Cách dùng trong component:
function SearchBox() {
  const [text, setText] = useState('');
  const debouncedQuery = useDebounce(text, 500);

  useEffect(() => {
    if (debouncedQuery) api.search(debouncedQuery);
  }, [debouncedQuery]);

  return <input value={text} onChange={e => setText(e.target.value)} />;
}

