export function usePrevious<T>(value: T): T | undefined {
  const ref = useRef<T>();

  useEffect(() => {
    // Cập nhật ref SAU KHI render xong
    ref.current = value;
  }, [value]);

  // Trả về giá trị của lần render TRƯỚC ĐÓ:
  return ref.current;
}

