// Sử dụng @tanstack/react-virtual (Modern Virtualizer):
import { useVirtualizer } from '@tanstack/react-virtual';
import { useRef } from 'react';

export function VirtualList({ items }: { items: string[] }) {
  const parentRef = useRef<HTMLDivElement>(null);

  const rowVirtualizer = useVirtualizer({
    count: items.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 40, // Ước lượng chiều cao mỗi dòng 40px
    overscan: 5 // Render thêm 5 dòng đệm phía trên và dưới
  });

  return (
    <div ref={parentRef} style={{ height: '400px', overflow: 'auto', border: '1px solid #ccc' }}>
      <div style={{ height: `${rowVirtualizer.getTotalSize()}px`, width: '100%', position: 'relative' }}>
        {rowVirtualizer.getVirtualItems().map(virtualRow => (
          <div
            key={virtualRow.index}
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: `${virtualRow.size}px`,
              transform: `translateY(${virtualRow.start}px)`
            }}
          >
            Dòng {virtualRow.index}: {items[virtualRow.index]}
          </div>
        ))}
      </div>
    </div>
  );
}

