// Custom hook hữu ích để debug nguyên nhân re-render:
function useWhyDidYouUpdate(name: string, props: Record<string, any>) {
  const prevProps = useRef<Record<string, any>>({});

  useEffect(() => {
    if (prevProps.current) {
      const allKeys = Object.keys({ ...prevProps.current, ...props });
      const changesObj: Record<string, any> = {};
      allKeys.forEach(key => {
        if (prevProps.current[key] !== props[key]) {
          changesObj[key] = { from: prevProps.current[key], to: props[key] };
        }
      });
      if (Object.keys(changesObj).length) {
        console.log(`[WhyDidYouUpdate] ${name}:`, changesObj);
      }
    }
    prevProps.current = props;
  });
}

