// Kỹ thuật 1: Two-pass Rendering (Chỉ render nội dung client sau khi đã mount)
function ClientOnlyTime() {
  const [hasMounted, setHasMounted] = useState(false);
  useEffect(() => {
    setHasMounted(true); // Đảm bảo chỉ chạy sau khi đã Hydrate xong
  }, []);

  if (!hasMounted) {
    return <span className="skeleton-placeholder">--:--</span>; // Khớp 100% với HTML Server
  }
  return <span>{new Date().toLocaleTimeString()}</span>;
}

